   const result={...item,version,context,prompt,title:r.title??item.title,model_answer,cefr_level:r.level,difficulty:r.level==='B2'?'hoog':'midden',estimated_duration_seconds:r.level==='A2'?45:60,practice_group:'quick-direct-'+r.group,learning_goal:r.goal,feedback_correct:explanation,feedback_incorrect:r.help,explanation,level_review:{source_level:item.cefr_level,level:r.level,reason:r.reason},source_ref:{...item.source_ref,review_version:version,changes:{context,prompt,title:r.title??item.title,help:r.help,goal:r.goal,level:r.level}}};
   const example=id+'@'+version;guidance.examples[example]={goal:r.goal,evidence:explanation,source:'quickArrangeBalanceReviewed'};
   guidance.bindings[id]={item_version:version,bank_id:bank.bank_id,erk:{status:'reviewed',version,source:'quickArrangeBalanceReviewed',levels:[r.level],skill:'Gesprekken voeren',goal:r.goal,evidence:r.reason+' Eigen redactioneel advies; geen niveautoets of klasproef.'},bow:{example,criteria:['goal','activate','support','feedback','close']}};
